using System.Globalization;
using System.Text.RegularExpressions;
using System.Text.Json.Nodes;

namespace NPS.Core.Alpha19;

public enum Alpha19PolicyFamily { Ncp, NwpMetadata, NwpSubscription, NipRenewal, NipRevocation, NipAdvisory, Ndp, Nop }

/// <summary>Side-effect-free alpha.19 decisions shared by runtimes and conformance runners.</summary>
public static partial class Alpha19Policies
{
    /// <summary>Canonical NPS status mappings for errors introduced by alpha.19.</summary>
    public static IReadOnlyDictionary<string, string> ErrorToNpsStatus { get; } =
        new Dictionary<string, string>(StringComparer.Ordinal)
        {
            ["NCP-EARLY-DATA-REJECTED"] = NpsStatusCodes.ProtoVersionIncompatible,
            ["NWP-SUBSCRIBE-LEASE-INVALID"] = NpsStatusCodes.ClientBadParam,
            ["NWP-SUBSCRIBE-LEASE-EXPIRED"] = NpsStatusCodes.ClientGone,
            ["NIP-OCSP-UNKNOWN"] = NpsStatusCodes.AuthUnauthenticated,
            ["NIP-REVOCATION-STATE-STALE"] = NpsStatusCodes.ServerUnavailable,
            ["NDP-STATE-UNAVAILABLE"] = NpsStatusCodes.ServerUnavailable,
            ["NDP-STATE-CORRUPT"] = NpsStatusCodes.ServerInternal,
            ["NOP-REPLAY-CONFLICT"] = NpsStatusCodes.ClientConflict,
            ["NOP-REPLAY-LIMIT"] = NpsStatusCodes.LimitResource,
            ["NOP-AGGREGATION-INVALID"] = NpsStatusCodes.ClientBadParam,
        };

    public static JsonObject Evaluate(Alpha19PolicyFamily family, JsonObject input) => family switch
    {
        Alpha19PolicyFamily.Ncp => Ncp(input),
        Alpha19PolicyFamily.NwpMetadata => NwpMetadata(input),
        Alpha19PolicyFamily.NwpSubscription => NwpSubscription(input),
        Alpha19PolicyFamily.NipRenewal => NipRenewal(input),
        Alpha19PolicyFamily.NipRevocation => NipRevocation(input),
        Alpha19PolicyFamily.NipAdvisory => NipAdvisory(input),
        Alpha19PolicyFamily.Ndp => Ndp(input),
        Alpha19PolicyFamily.Nop => Nop(input),
        _ => throw new ArgumentOutOfRangeException(nameof(family))
    };

    private static JsonObject Ncp(JsonObject i)
    {
        if (i.ContainsKey("client_ping_ms")) { var offers = new[] { Int(i, "client_ping_ms"), Int(i, "server_ping_ms") }.Where(x => x > 0).ToArray(); return new() { ["keepalive_enabled"] = offers.Length > 0, ["effective_interval_ms"] = offers.Length == 0 ? null : Math.Max(1000, offers.Min()) }; }
        if (i["events"] is JsonArray events) { var clock = Int(i, "last_valid_inbound_ms"); foreach (var raw in events.OfType<JsonObject>()) if (Str(raw, "event") == "valid_inbound_frame") clock = Int(raw, "at_ms"); return new() { { "last_valid_inbound_ms", clock } }; }
        if (i.ContainsKey("queued_probe_count")) { var due = Int(i, "evaluate_at_ms") - Int(i, "last_application_send_ms") >= Int(i, "effective_interval_ms"); return due && Int(i, "queued_probe_count") == 0 ? new() { { "enqueue", new JsonObject { { "frame", "0x07" }, { "payload_length", 0 } } }, { "queued_probe_count", 1 } } : new() { { "queued_probe_count", Int(i, "queued_probe_count") } }; }
        if (i.ContainsKey("active_streams")) return Int(i, "evaluate_at_ms") >= Int(i, "last_valid_inbound_ms") + 3 * Int(i, "effective_interval_ms") ? new() { { "state", "closing" }, { "error", "NCP-KEEPALIVE-TIMEOUT" }, { "error_count", 1 }, { "cancelled_streams", Int(i, "active_streams") }, { "close_by_ms", Int(i, "evaluate_at_ms") + 500 }, { "allow_later_application_frames", false } } : new() { { "state", "open" } };
        if (i.ContainsKey("payload_length")) return Int(i, "payload_length") == 0 ? new() { { "accepted", true }, { "last_valid_inbound_ms", Int(i, "received_at_ms") } } : new() { { "accepted", false }, { "error", "NCP-FRAME-PAYLOAD-TOO-LARGE" }, { "last_valid_inbound_ms", Int(i, "last_valid_inbound_ms") } };
        if (i.ContainsKey("early_data")) return Str(i, "carrier") == "quic" && !Bool(i, "handshake_confirmed") ? new() { { "accepted", false }, { "error", "NCP-EARLY-DATA-REJECTED" }, { "retry_after_confirmation", true } } : new() { { "accepted", true } };
        if (i.ContainsKey("bound_nid")) { if (!Bool(i, "handshake_confirmed") || Str(i, "bound_nid") != Str(i, "migrated_nid")) return new() { { "migration_allowed", false }, { "session_preserved", false }, { "error", "NCP-NID-MISMATCH" } }; var send = Int(i, "carrier_credit_bytes") > 0 && Int(i, "ncp_window_cgn") > 0; var o = new JsonObject { { "migration_allowed", true }, { "session_preserved", true }, { "send_allowed", send } }; if (!send) o["reason"] = Int(i, "ncp_window_cgn") <= 0 ? "ncp_window_exhausted" : "carrier_credit_exhausted"; return o; }
        throw new ArgumentException("Unknown NCP input.");
    }

    private static (JsonObject Value, JsonArray Diagnostics) Sla(JsonObject s, string prefix = "") { var o = new JsonObject(); var d = new JsonArray(); if (s.ContainsKey("p95_latency_ms")) { var n = Int(s, "p95_latency_ms"); if (n > 0) o["p95_latency_ms"] = n; else d.Add(prefix + "p95_latency_ms"); } if (s.ContainsKey("availability")) { var text = Str(s, "availability"); var ok = decimal.TryParse(text, NumberStyles.Number, CultureInfo.InvariantCulture, out var n) && n > 0 && n <= 1; if (ok) o["availability"] = text; else d.Add(prefix + "availability"); } if (s.ContainsKey("sla_tier")) { var t = Str(s, "sla_tier"); var ranks = new Dictionary<string, int> { { "basic", 0 }, { "standard", 1 }, { "premium", 2 } }; if (ranks.TryGetValue(t, out var rank)) { o["sla_tier"] = t; o["sla_tier_rank"] = rank; } else { o["sla_tier_raw"] = t; o["sla_tier_rank"] = null; } } return (o, d); }
    private static JsonObject NwpMetadata(JsonObject i)
    {
        if (i.ContainsKey("stability")) { if (i["stability"] is null) return new() { { "normalized", "stable" }, { "diagnostics", new JsonArray() } }; var v = Str(i, "stability"); return new() { { "raw", v }, { "normalized", v is "experimental" or "stable" or "deprecated" ? v : "experimental" }, { "rank_as_stable", v == "stable" } }; }
        if (i["sla"] is JsonObject sla) { var n = Sla(sla); return new() { { "manifest_valid", true }, { "normalized_sla", n.Value }, { "diagnostics", n.Diagnostics } }; }
        if (i["billing"] is JsonObject b) { var p = Str(b, "metering_profile"); if (p is not ("free" or "metered")) p = "metered"; var n = new JsonObject { { "metering_profile", p } }; var d = new JsonArray(); if (p == "free") { foreach (var k in new[] { "billing_unit", "price_hint", "currency" }) if (b.ContainsKey(k)) d.Add(k); } else { var unit = Str(b, "billing_unit"); if (unit.Length > 0) n["billing_unit"] = unit; else d.Add("billing_unit"); if (b.ContainsKey("price_hint")) { var price = Str(b, "price_hint"); if (Price().IsMatch(price)) { if (b.ContainsKey("currency") && Str(b, "currency") != price[..3]) d.Add("currency"); else { n["price_hint"] = price; if (b.ContainsKey("currency")) n["currency"] = Str(b, "currency"); } } else d.Add("price_hint"); } } return new() { { "normalized_billing", n }, { "diagnostics", d } }; }
        if (i["top_level"] is JsonObject top) { var baseSla = Sla(Obj(top, "sla")); var a = Sla(Obj(Obj(i, "action"), "sla"), "action.sla."); foreach (var pair in a.Value) baseSla.Value[pair.Key] = pair.Value?.DeepClone(); return new() { { "effective_sla", baseSla.Value }, { "diagnostics", a.Diagnostics } }; }
        throw new ArgumentException("Unknown NWP metadata input.");
    }

    private static JsonObject NwpSubscription(JsonObject i)
    {
        if (i["policy"] is JsonObject p) { var r = Obj(i, "request"); var def = Int(p, "default_lease_seconds"); var max = Int(p, "max_lease_seconds"); var renew = Int(p, "renew_before_seconds"); if (def <= 0 || max <= 0 || def > max || renew >= max) return new() { { "accepted", false }, { "error", "NWP-SUBSCRIBE-LEASE-INVALID" }, { "state_mutated", false } }; var lease = r.ContainsKey("lease_seconds") ? Int(r, "lease_seconds") : def; if (lease <= 0) return new() { { "accepted", false }, { "error", "NWP-SUBSCRIBE-LEASE-INVALID" }, { "state_mutated", false } }; lease = Math.Min(lease, max); var o = new JsonObject { { "lease_seconds", lease }, { "expires_at", Time(i, "accepted_at").AddSeconds(lease).ToString("yyyy-MM-dd'T'HH:mm:ss'Z'", CultureInfo.InvariantCulture) } }; if (!r.ContainsKey("lease_seconds")) o["status"] = "open"; return o; }
        if (i.ContainsKey("owner_nid")) return Str(i, "owner_nid") == Str(i, "caller_nid") ? new() { { "accepted", true } } : new() { { "accepted", false }, { "error", "NWP-AUTH-NID-SCOPE-VIOLATION" }, { "state_disclosed", false } };
        if (i.ContainsKey("prior_seq")) return new() { { "expires_at", Time(i, "accepted_at").AddSeconds(Int(i, "lease_seconds")).ToString("yyyy-MM-dd'T'HH:mm:ss'Z'", CultureInfo.InvariantCulture) }, { "seq", Int(i, "prior_seq") }, { "cursor", Str(i, "prior_cursor") } };
        if (i.ContainsKey("expires_at")) return Time(i, "now") >= Time(i, "expires_at") ? new() { { "accepted", false }, { "status", "closed" }, { "error", "NWP-SUBSCRIBE-LEASE-EXPIRED" }, { "terminal_event_count", 1 } } : new() { { "accepted", true } };
        if (Str(i, "operation") is "renew" or "close" && new[] { "anchor_ref", "filter", "type" }.Any(i.ContainsKey)) return new() { { "accepted", false }, { "error", "NWP-SUBSCRIBE-LEASE-INVALID" }, { "state_mutated", false } };
        throw new ArgumentException("Unknown NWP subscription input.");
    }

    private static JsonObject NipRenewal(JsonObject i) { if (Str(i, "profile") == "standard") { var open = Time(i, "not_after") - Time(i, "now") <= TimeSpan.FromDays(7); return new() { { "renewal_open", open }, { "error", open ? null : "NIP-CA-RENEWAL-TOO-EARLY" } }; } if (Str(i, "profile") == "short-lived-edge") { var w = Int(i, "original_validity_seconds") / 4; return new() { { "renewal_open", Int(i, "remaining_seconds") <= w }, { "window_seconds", w } }; } if (i["current"] is JsonObject c) { var r = Obj(i, "requested"); var allowed = Subset(Arr(r, "capabilities"), Arr(c, "capabilities")) && Subset(Arr(r, "scope"), Arr(c, "scope")); return allowed ? new() { { "issued", true } } : new() { { "issued", false }, { "error", "NIP-CA-SCOPE-EXPANSION-DENIED" } }; } if (i["recorded"] is JsonObject record) return Bool(record, "committed") && Str(record, "canonical_digest") == Str(i, "canonical_digest") ? new() { { "serial", Str(record, "serial") }, { "new_issue_count", 0 } } : new() { { "error", "NIP-CA-SERIAL-DUPLICATE" }, { "new_issue_count", 0 } }; if (i.ContainsKey("old_ticket_not_after")) return new() { { "old_ticket_not_after", Str(i, "old_ticket_not_after") } }; throw new ArgumentException("Unknown renewal input."); }
    private static JsonObject NipRevocation(JsonObject i) { if (i["cached"] is JsonObject c) { var n = Obj(i, "incoming"); var replace = Bool(n, "signature_valid") && Time(n, "this_update") > Time(c, "this_update"); return new() { { "cache_replaced", replace }, { "effective_outcome", Str(replace ? n : c, "outcome") } }; } var consulted = new JsonArray(); var diagnostics = new JsonArray(); var hasNow = i.ContainsKey("now"); foreach (var raw in Arr(i, "sources").OfType<JsonObject>()) { var name = Str(raw, "source"); var outcome = Str(raw, "outcome"); consulted.Add(name); if (outcome == "unknown") return new() { { "valid", false }, { "error", "NIP-OCSP-UNKNOWN" } }; if (hasNow && raw.ContainsKey("next_update") && Time(i, "now") >= Time(raw, "next_update")) { diagnostics.Add(name + "_stale"); continue; } if (outcome == "revoked") return new() { { "valid", false }, { "error", "NIP-CERT-REVOKED" } }; if (outcome == "good") { var o = new JsonObject { { "valid", true }, { "consulted_sources", consulted } }; if (diagnostics.Count > 0) o["diagnostics"] = diagnostics; return o; } } return Str(i, "revocation_mode") == "required" ? new() { { "valid", false }, { "error", "NIP-REVOCATION-STATE-STALE" } } : new() { { "valid", true }, { "consulted_sources", consulted } }; }
    private static JsonObject NipAdvisory(JsonObject i) { var ident = Obj(i, "ident"); var ext = Obj(i, "certificate_extensions"); var f = new List<JsonObject>(); if (Str(ident, "assurance_level") != Str(ext, "assurance_level")) f.Add(new() { { "field", "assurance_level" }, { "error", "NIP-ASSURANCE-MISMATCH" } }); if (!Subset(Arr(ident, "capabilities"), Arr(ext, "capabilities"))) f.Add(new() { { "field", "capabilities" }, { "error", "NIP-CERT-CAPABILITIES-EXCEEDED" } }); if (!Subset(Arr(ident, "node_roles"), Arr(ext, "node_roles"))) f.Add(new() { { "field", "node_roles" }, { "error", "NIP-CERT-NODE-ROLES-MISMATCH" } }); if (ident["ocsp_staple"] is null) f.Add(new() { { "field", "ocsp_staple" }, { "error", "NIP-OCSP-STAPLE-EXPIRED" } }); var a = new JsonArray(f.OrderBy(x => Str(x, "field")).Select(x => (JsonNode)x).ToArray()); return new() { { "accepted_current_request", !Bool(i, "phase3_enforcement") }, { "findings", a }, { "state_mutated", false } }; }

    private static JsonObject Ndp(JsonObject i) { if (i.ContainsKey("commit")) return Str(i, "commit") == "success" ? new() { { "acknowledged", true }, { "served_seq", Int(i, "incoming_seq") }, { "persisted_seq", Int(i, "incoming_seq") } } : new() { { "acknowledged", false }, { "served_seq", Int(i, "persisted_seq") }, { "persisted_seq", Int(i, "persisted_seq") }, { "error", "NDP-STATE-UNAVAILABLE" } }; if (i.ContainsKey("now")) { var r = Obj(i, "record"); return new() { { "live_entry", Time(r, "fresh_until") > Time(i, "now") }, { "highest_seq", Int(r, "highest_seq") }, { "ready", true } }; } if (i.ContainsKey("restored_highest_seq")) return Int(i, "incoming_seq") < Int(i, "restored_highest_seq") ? new() { { "accepted", false }, { "highest_seq", Int(i, "restored_highest_seq") }, { "error", "NDP-GRAPH-SEQ-ROLLBACK" } } : new() { { "accepted", true }, { "highest_seq", Int(i, "incoming_seq") } }; if (i.ContainsKey("owners")) { var live = Arr(i, "owners").OfType<JsonObject>().Where(x => Bool(x, "live")).ToArray(); var top = live.Max(x => Int(x, "epoch")); var leaders = live.Where(x => Int(x, "epoch") == top).Select(x => Str(x, "nid")).Order().ToArray(); return leaders.Length == 1 ? new() { { "resolved_nid", leaders[0] } } : new() { { "resolved_nid", null }, { "error", "NDP-CLUSTER-SPLIT" } }; } if (i.ContainsKey("snapshot_validation")) return Str(i, "snapshot_validation") == "valid" ? new() { { "ready", true }, { "started_empty", false } } : new() { { "ready", false }, { "started_empty", false }, { "error", "NDP-STATE-CORRUPT" } }; if (i.ContainsKey("profiles")) return new() { { "recovery", new JsonArray(Arr(i, "profiles").Select(x => (JsonNode)(Str(x) == "local-dev" ? "volatile" : "durable")).ToArray()) } }; if (i.ContainsKey("revoked_origin")) { var r = Obj(i, "record"); return new() { { "live", Bool(r, "live") && Str(r, "origin") != Str(i, "revoked_origin") }, { "highest_seq", Int(r, "highest_seq") } }; } throw new ArgumentException("Unknown NDP input."); }
    private static JsonObject Nop(JsonObject i) { if (i["recorded"] is JsonObject r && Str(r, "digest") == Str(i, "digest")) return new() { { "state", Str(r, "state") }, { "dispatch_count", Int(r, "dispatch_count") }, { "replayed", true } }; if (i.ContainsKey("recorded_digest")) return Str(i, "digest") != Str(i, "recorded_digest") ? new() { { "accepted", false }, { "error", "NOP-REPLAY-CONFLICT" }, { "record_mutated", false } } : new() { { "accepted", true } }; if (i["incoming"] is JsonObject incoming) { var found = Arr(i, "records").OfType<JsonObject>().Any(x => Str(x, "caller_nid") == Str(incoming, "caller_nid") && Str(x, "task_id") == Str(incoming, "task_id")); return new() { { "new_key", !found }, { "accepted", !found } }; } if (i.ContainsKey("terminal_commit_ms")) return Int(i, "query_at_ms") >= Int(i, "terminal_commit_ms") + 1000 * Int(i, "result_ttl_seconds") ? new() { { "result", null }, { "error", "NOP-TASK-RESULT-EXPIRED" } } : new() { { "result", "retained" } }; if (i.ContainsKey("result_expired_at_ms")) { var retained = Int(i, "duplicate_at_ms") < Int(i, "result_expired_at_ms") + 1000 * Int(i, "replay_tombstone_seconds"); return retained ? new() { { "dispatch", false }, { "error", "NOP-TASK-RESULT-EXPIRED" }, { "tombstone_retained", true } } : new() { { "dispatch", true }, { "tombstone_retained", false } }; } if (i.ContainsKey("capacity")) { var records = Arr(i, "records").OfType<JsonObject>().ToArray(); var safe = records.Where(x => Str(x, "state") != "running").ToArray(); if (records.Length >= Int(i, "capacity") && safe.Length == 0) return new() { { "accepted", false }, { "evicted", new JsonArray() }, { "error", "NOP-REPLAY-LIMIT" } }; return new() { { "accepted", true }, { "evicted", new JsonArray(safe.Take(1).Select(x => (JsonNode)Str(x, "key")).ToArray()) } }; } if (i["committed"] is JsonObject committed) return new() { { "state", Str(committed, "state") }, { "late_event", "audit_only" }, { "ttl_extended", false } }; if (i.ContainsKey("min_required")) { var results = Arr(i, "results").OfType<JsonObject>().ToArray(); if (results.Any(x => !x.ContainsKey("score") || !double.IsFinite(Double(x, "score")))) return new() { { "error", "NOP-AGGREGATION-INVALID" } }; var selected = results.OrderByDescending(x => Double(x, "score")).ThenBy(x => Str(x, "node_id")).Take(Int(i, "min_required")); return new() { { "selected_node_ids", new JsonArray(selected.Select(x => (JsonNode)Str(x, "node_id")).ToArray()) } }; } if (i.ContainsKey("topology_order")) { var by = Arr(i, "results").OfType<JsonObject>().ToDictionary(x => Str(x, "node_id")); var agg = new JsonObject(); foreach (var id in Arr(i, "topology_order").Select(Str)) { if (!by.TryGetValue(id, out var item) || Str(item, "state") != "completed") continue; foreach (var pair in Obj(item, "value")) { if (agg[pair.Key] is JsonArray left && pair.Value is JsonArray right) foreach (var value in right) left.Add(value?.DeepClone()); else agg[pair.Key] = pair.Value?.DeepClone(); } } return new() { { "aggregated", agg }, { "inputs_mutated", false } }; } throw new ArgumentException("Unknown NOP input."); }

    private static int Int(JsonObject o, string k) => o[k]!.GetValue<int>(); private static double Double(JsonObject o, string k) => o[k]!.GetValue<double>();
    private static string Str(JsonObject o, string k) => o[k]?.GetValue<string>() ?? ""; private static string Str(JsonNode? n) => n?.GetValue<string>() ?? "";
    private static bool Bool(JsonObject o, string k) => o[k]?.GetValue<bool>() ?? false; private static JsonObject Obj(JsonObject o, string k) => o[k] as JsonObject ?? new();
    private static JsonArray Arr(JsonObject o, string k) => o[k] as JsonArray ?? new(); private static DateTimeOffset Time(JsonObject o, string k) => DateTimeOffset.Parse(Str(o, k), CultureInfo.InvariantCulture, DateTimeStyles.AssumeUniversal);
    private static bool Subset(JsonArray want, JsonArray have) { var set = have.Select(Str).ToHashSet(StringComparer.Ordinal); return want.Select(Str).All(set.Contains); }
    [GeneratedRegex("^[A-Z]{3} [0-9]+(?:\\.[0-9]+)?$", RegexOptions.CultureInvariant)] private static partial Regex Price();
}
